public class Main {
    public static void main(String[] args) {
        String storeName = "FreshMart Supermarket";
        String cashier = "Amit";
        int invoiceNo = 4821;

        System.out.printf("===== %s =====%n", storeName);
        System.out.printf("Invoice: #%06d | Cashier: %s%n", invoiceNo, cashier);
        System.out.println("----------------------------------------");
        System.out.printf("%-15s %5s %8s %10s%n", "Product", "Qty", "Rate", "Total");
        System.out.println("----------------------------------------");

        String item1 = "Basmati Rice";
        int q1 = 2;
        double rate1 = 110.0;
        double tot1 = q1 * rate1;
        System.out.printf("%-15s %5d %8.2f %10.2f%n", item1, q1, rate1, tot1);

        String item2 = "Pure Milk 1L";
        int q2 = 3;
        double rate2 = 32.5;
        double tot2 = q2 * rate2;
        System.out.printf("%-15s %5d %8.2f %10.2f%n", item2, q2, rate2, tot2);

        double subtotal = tot1 + tot2;
        double tax = subtotal * 0.05;
        double grandTotal = subtotal + tax;

        System.out.println("----------------------------------------");
        System.out.printf("%-29s %10.2f%n", "Subtotal:", subtotal);
        System.out.printf("%-29s %10.2f%n", "Tax (5%):", tax);
        System.out.printf("%-29s %10.2f%n", "GRAND TOTAL:", grandTotal);
        System.out.println("========================================");
    }
}

